const product = $('Webhook — Produit pricé reçu').first().json;
const cjResults = $('CJ Dropshipping — Chercher produit').first().json?.data?.list || [];
const aeResults = $('AliExpress — Détails fournisseur').first().json?.aliexpress_affiliate_product_query_response?.resp_result?.result?.products?.product || [];
const spocketResults = $('Spocket — Fournisseurs EU/CH').first().json?.products || [];

function scoreSupplier(s) {
  const rating = parseFloat(s.rating || s.evaluate_rate || 4.5);
  const orders = parseInt(s.orders || s.lastest_volume || 100);
  const shippingDays = parseInt(s.shipping_days_eu || s.ship_to_days || 14);
  const price = parseFloat(s.price || s.sale_price || 999);

  if (rating < 4.7 || orders < 500) return -1;

  return (rating * 10)
    + (orders > 1000 ? 15 : 5)
    - (shippingDays * 2)
    - (price * 0.5);
}

const allSuppliers = [
  ...cjResults.map(s => ({ ...s, source: 'cj_dropshipping', price: s.sellPrice, rating: s.productRating || 4.8, orders: s.totalOrders || 0, shipping_days_eu: 7 })),
  ...aeResults.map(s => ({ ...s, source: 'aliexpress', price: s.sale_price, rating: s.evaluate_rate, orders: s.lastest_volume, shipping_days_eu: 14 })),
  ...spocketResults.map(s => ({ ...s, source: 'spocket', price: s.wholesale_price, rating: s.supplier?.rating || 4.9, orders: s.supplier?.fulfilled_orders || 0, shipping_days_eu: 5 }))
];

const scored = allSuppliers
  .map(s => ({ ...s, score_sourcing: scoreSupplier(s) }))
  .filter(s => s.score_sourcing > 0)
  .sort((a, b) => b.score_sourcing - a.score_sourcing);

if (!scored.length) {
  return [{ json: { ...product, verdict_sourcing: 'REJETE', raison: 'Aucun fournisseur qualifié (rating < 4.7 ou orders < 500)' } }];
}

const best = scored[0];

return [{
  json: {
    ...product,
    supplier: {
      source: best.source,
      id: best.product_id || best.pid || best.id,
      name: best.productNameEn || best.product_title || best.name,
      price_chf: best.price,
      rating: best.rating,
      orders: best.orders,
      shipping_days_eu: best.shipping_days_eu,
      images: [
        best.product_main_image_url || best.image_url || '',
        ...(best.product_small_image_urls?.string || [])
      ].filter(Boolean).slice(0, 8),
      video_url: best.product_video_url || null,
      variants: best.sku_info || best.variants || [],
      score_sourcing: best.score_sourcing
    },
    verdict_sourcing: 'VALIDE'
  }
}];

const product = $('Scorer et sélectionner le meilleur fournisseur').first().json;
const rawReviews = $('Récupérer les meilleures reviews').first().json?.feedbacks || [];

const topReviews = rawReviews
  .filter(r => r.starRating >= 4)
  .sort((a, b) => b.starRating - a.starRating || (b.images?.length || 0) - (a.images?.length || 0))
  .slice(0, 20)
  .map(r => ({
    rating: r.starRating,
    text_original: r.buyerFeedback,
    author: r.buyerName || 'Client vérifié',
    date: r.gmtCreate,
    images: r.images || [],
    country: r.buyerCountry || ''
  }));

return [{ json: { ...product, reviews_raw: topReviews } }];
